using ClinicaEsteticaWeb.Models;using ClinicaEsteticaWeb.Services;using MySqlConnector;using Microsoft.AspNetCore.Mvc;
namespace ClinicaEsteticaWeb.Controllers;
public class AgendamentosController:Controller {private readonly Db _db;public AgendamentosController(Db db)=>_db=db;public IActionResult Index(){var l=new List<Agendamento>();using var x=_db.Open();using var c=new MySqlCommand("SELECT a.*,c.nome cliente,p.nome profissional FROM agendamento a JOIN cliente c ON c.id=a.cliente_id JOIN profissional p ON p.id=a.profissional_id ORDER BY a.data,a.hora_inicio",x);using var r=c.ExecuteReader();while(r.Read())l.Add(new Agendamento{Id=r.GetInt32("id"),ClienteId=r.GetInt32("cliente_id"),ProfissionalId=r.GetInt32("profissional_id"),Data=r.GetDateTime("data"),HoraInicio=r.GetTimeSpan("hora_inicio"),HoraFim=r.GetTimeSpan("hora_fim"),Situacao=r.GetString("situacao"),ValorTotal=r.GetDecimal("valor_total"),ClienteNome=r.GetString("cliente"),ProfissionalNome=r.GetString("profissional")});return View(l);}[HttpGet]public IActionResult Create(){using var x=_db.Open();ViewBag.Clientes=LoadPairs(x,"cliente","nome");ViewBag.Profissionais=LoadPairs(x,"profissional","nome");ViewBag.Procedimentos=LoadProcedimentos(x);return View(new AgendamentoForm{Data=DateTime.Today});}[HttpPost][ValidateAntiForgeryToken]public IActionResult Create(AgendamentoForm f){using var x=_db.Open();using var conflict=new MySqlCommand("SELECT COUNT(*) FROM agendamento WHERE profissional_id=@p AND data=@d AND situacao<>'cancelado' AND hora_inicio<@fim AND hora_fim>@inicio",x);conflict.Parameters.AddWithValue("@p",f.ProfissionalId);conflict.Parameters.AddWithValue("@d",f.Data.Date);conflict.Parameters.AddWithValue("@inicio",f.HoraInicio);conflict.Parameters.AddWithValue("@fim",f.HoraFim);if(Convert.ToInt64(conflict.ExecuteScalar())>0){ModelState.AddModelError("","O profissional já possui atendimento em horário sobreposto.");ViewBag.Clientes=LoadPairs(x,"cliente","nome");ViewBag.Profissionais=LoadPairs(x,"profissional","nome");ViewBag.Procedimentos=LoadProcedimentos(x);return View(f);}var ids=f.ProcedimentosIds??[];if(ids.Length==0){ModelState.AddModelError("","Selecione ao menos um procedimento.");ViewBag.Clientes=LoadPairs(x,"cliente","nome");ViewBag.Profissionais=LoadPairs(x,"profissional","nome");ViewBag.Procedimentos=LoadProcedimentos(x);return View(f);}decimal total=0;var prices=new List<(int id,decimal v)>();foreach(var id in ids){using var pc=new MySqlCommand("SELECT valor FROM procedimento WHERE id=@id AND status='ativo'",x);pc.Parameters.AddWithValue("@id",id);var o=pc.ExecuteScalar();if(o!=null){var v=Convert.ToDecimal(o);total+=v;prices.Add((id,v));}}using var tx=x.BeginTransaction();try{using var c=new MySqlCommand("INSERT INTO agendamento(cliente_id,profissional_id,data,hora_inicio,hora_fim,situacao,valor_total) VALUES(@c,@p,@d,@i,@f,@s,@v); SELECT LAST_INSERT_ID();",x,tx);c.Parameters.AddWithValue("@c",f.ClienteId);c.Parameters.AddWithValue("@p",f.ProfissionalId);c.Parameters.AddWithValue("@d",f.Data.Date);c.Parameters.AddWithValue("@i",f.HoraInicio);c.Parameters.AddWithValue("@f",f.HoraFim);c.Parameters.AddWithValue("@s",f.Situacao);c.Parameters.AddWithValue("@v",total);var aid=Convert.ToInt32(c.ExecuteScalar());foreach(var q in prices){using var pc=new MySqlCommand("INSERT INTO agendamento_procedimento(agendamento_id,procedimento_id,valor_cobrado) VALUES(@a,@p,@v)",x,tx);pc.Parameters.AddWithValue("@a",aid);pc.Parameters.AddWithValue("@p",q.id);pc.Parameters.AddWithValue("@v",q.v);pc.ExecuteNonQuery();}tx.Commit();return RedirectToAction(nameof(Index));}catch{tx.Rollback();throw;}}[HttpPost][ValidateAntiForgeryToken]public IActionResult Cancel(int id){using var x=_db.Open();using var c=new MySqlCommand("UPDATE agendamento SET situacao='cancelado' WHERE id=@id",x);c.Parameters.AddWithValue("@id",id);c.ExecuteNonQuery();return RedirectToAction(nameof(Index));}private static List<(int,string)> LoadPairs(MySqlConnection x,string table,string name){var l=new List<(int,string)>();using var c=new MySqlCommand($"SELECT id,{name} FROM {table} WHERE status='ativo' ORDER BY {name}",x);using var r=c.ExecuteReader();while(r.Read())l.Add((r.GetInt32(0),r.GetString(1)));return l;}private static List<(int,string,decimal)> LoadProcedimentos(MySqlConnection x){var l=new List<(int,string,decimal)>();using var c=new MySqlCommand("SELECT id,nome,valor FROM procedimento WHERE status='ativo' ORDER BY nome",x);using var r=c.ExecuteReader();while(r.Read())l.Add((r.GetInt32(0),r.GetString(1),r.GetDecimal(2)));return l;}}
